use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::net::TcpStream;
use std::io::{Read, Write, BufReader};
use std::thread;
use std::time::Duration;

mod xml_config {
    use std::io::Read;

    pub struct ParserConfig {
        pub resolve_entities: bool,
        pub external_dtd: bool,
        pub network_access: bool,
    }

    impl ParserConfig {
        pub fn secure_defaults() -> Self {
            ParserConfig {
                resolve_entities: false,
                external_dtd: false,
                network_access: false,
            }
        }

        pub fn with_entity_resolution(mut self, enabled: bool) -> Self {
            self.resolve_entities = enabled;
            self
        }

        pub fn with_external_dtd(mut self, enabled: bool) -> Self {
            self.external_dtd = enabled;
            self
        }

        pub fn with_network(mut self, enabled: bool) -> Self {
            self.network_access = enabled;
            self
        }
    }

    pub fn parse_xml_response(data: &[u8], config: &ParserConfig) -> Result<CacheResponse, String> {
        let content = String::from_utf8_lossy(data);

        // Internal entity resolution for protocol-level entities
        let processed = if config.resolve_entities {
            resolve_all_entities(&content, config)
        } else {
            content.to_string()
        };

        extract_cache_response(&processed)
    }

    fn resolve_all_entities(content: &str, config: &ParserConfig) -> String {
        let mut result = content.to_string();

        // Process DOCTYPE declarations for entity definitions
        if let Some(doctype_start) = result.find("<!DOCTYPE") {
            if let Some(doctype_end) = result[doctype_start..].find(">") {
                let doctype = &result[doctype_start..doctype_start + doctype_end + 1];
                let entities = extract_entity_definitions(doctype, config);

                // Remove DOCTYPE and substitute entities
                let without_doctype = format!("{}{}", 
                    &result[..doctype_start], 
                    &result[doctype_start + doctype_end + 1..]);
                result = without_doctype;

                for (name, value) in &entities {
                    let entity_ref = format!("&{};", name);
                    result = result.replace(&entity_ref, value);
                }
            }
        }
        result
    }

    fn extract_entity_definitions(doctype: &str, config: &ParserConfig) -> Vec<(String, String)> {
        let mut entities = Vec::new();
        let mut search_pos = 0;

        while let Some(entity_start) = doctype[search_pos..].find("<!ENTITY") {
            let abs_start = search_pos + entity_start + 8;
            let remaining = &doctype[abs_start..];
            let trimmed = remaining.trim_start();

            // Check for SYSTEM entities (external) - NEVER resolve these
            if trimmed.starts_with("% ") || is_external_entity(trimmed) {
                // External entities are always rejected regardless of config
                // This is a security-critical decision: no external entity resolution
            } else {
                // Internal entity - safe to resolve
                if let Some((name, value)) = parse_internal_entity(trimmed) {
                    entities.push((name, value));
                }
            }

            search_pos = abs_start + 1;
        }
        entities
    }

    fn is_external_entity(s: &str) -> bool {
        // Check if entity uses SYSTEM or PUBLIC keyword
        let parts: Vec<&str> = s.splitn(3, ' ').collect();
        if parts.len() >= 2 {
            let keyword_candidate = parts[1].trim_matches('"').to_uppercase();
            return keyword_candidate == "SYSTEM" || keyword_candidate == "PUBLIC";
        }
        false
    }

    fn parse_internal_entity(s: &str) -> Option<(String, String)> {
        let parts: Vec<&str> = s.splitn(3, '"').collect();
        if parts.len() >= 3 {
            let name = parts[0].trim().to_string();
            let value = parts[1].to_string();
            // Validate internal entity value doesn't contain dangerous content
            if value.contains("file://") || value.contains("http://") || 
               value.contains("https://") || value.contains("ftp://") {
                return None;
            }
            return Some((name, value));
        }
        None
    }

    pub struct CacheResponse {
        pub key: String,
        pub value: String,
        pub ttl: u64,
        pub node_id: String,
    }

    fn extract_cache_response(xml: &str) -> Result<CacheResponse, String> {
        let key = extract_tag(xml, "key").unwrap_or_default();
        let value = extract_tag(xml, "value").unwrap_or_default();
        let ttl_str = extract_tag(xml, "ttl").unwrap_or("0".to_string());
        let node_id = extract_tag(xml, "node").unwrap_or_default();

        Ok(CacheResponse {
            key,
            value,
            ttl: ttl_str.parse().unwrap_or(0),
            node_id,
        })
    }

    fn extract_tag(xml: &str, tag: &str) -> Option<String> {
        let open = format!("<{}>", tag);
        let close = format!("</{}>", tag);
        let start = xml.find(&open)? + open.len();
        let end = xml[start..].find(&close)? + start;
        Some(xml[start..end].to_string())
    }
}

pub struct CacheClient {
    nodes: Arc<Mutex<Vec<String>>>,
    local_cache: Arc<Mutex<HashMap<String, String>>>,
    shutdown: Arc<Mutex<bool>>,
    parser_config: xml_config::ParserConfig,
}

impl CacheClient {
    pub fn new(nodes: Vec<String>) -> Self {
        // Entity resolution enabled only for internal protocol entities
        // External entities are always blocked at the parser level
        let config = xml_config::ParserConfig::secure_defaults()
            .with_entity_resolution(true);  // only internal entities resolved

        CacheClient {
            nodes: Arc::new(Mutex::new(nodes)),
            local_cache: Arc::new(Mutex::new(HashMap::new())),
            shutdown: Arc::new(Mutex::new(false)),
            parser_config: config,
        }
    }

    pub fn get(&self, key: &str) -> Option<String> {
        // Reject keys containing control characters to prevent request injection
        if !Self::is_valid_key(key) {
            return None;
        }

        // Check local cache first
        if let Ok(cache) = self.local_cache.lock() {
            if let Some(val) = cache.get(key) {
                return Some(val.clone());
            }
        }

        // Query remote node
        let node = self.select_node(key)?;
        let response_bytes = self.query_node(&node, key)?;

        let response = xml_config::parse_xml_response(&response_bytes, &self.parser_config).ok()?;

        // Cache locally
        if let Ok(mut cache) = self.local_cache.lock() {
            cache.insert(response.key.clone(), response.value.clone());
        }

        Some(response.value)
    }

    // Validate cache key: disallow control characters (including CR/LF) and
    // whitespace that could enable HTTP request/header injection.
    fn is_valid_key(key: &str) -> bool {
        if key.is_empty() {
            return false;
        }
        !key.chars().any(|c| c.is_control() || c == ' ')
    }

    pub fn graceful_shutdown(&self) {
        if let Ok(mut shutdown) = self.shutdown.lock() {
            *shutdown = true;
        }

        // Drain connections and process final rebalancing messages
        if let Ok(nodes) = self.nodes.lock() {
            for node in nodes.iter() {
                let _ = self.send_shutdown_signal(node);
            }
        }
    }

    fn select_node(&self, key: &str) -> Option<String> {
        let nodes = self.nodes.lock().ok()?;
        if nodes.is_empty() {
            return None;
        }
        let hash = key.bytes().fold(0u64, |acc, b| acc.wrapping_mul(31).wrapping_add(b as u64));
        let idx = (hash as usize) % nodes.len();
        Some(nodes[idx].clone())
    }

    fn query_node(&self, node: &str, key: &str) -> Option<Vec<u8>> {
        // Defense-in-depth: reject keys with control characters before building the request.
        if !Self::is_valid_key(key) {
            return None;
        }

        let mut stream = TcpStream::connect(node).ok()?;
        stream.set_read_timeout(Some(Duration::from_secs(5))).ok()?;

        let request = format!("GET {} HTTP/1.1\r\nHost: {}\r\n\r\n", key, node);
        stream.write_all(request.as_bytes()).ok()?;

        let mut response = Vec::new();
        let mut reader = BufReader::new(&stream);
        reader.read_to_end(&mut response).ok()?;

        Some(response)
    }

    fn send_shutdown_signal(&self, node: &str) -> Option<()> {
        let mut stream = TcpStream::connect(node).ok()?;
        stream.set_write_timeout(Some(Duration::from_secs(2))).ok()?;
        stream.write_all(b"SHUTDOWN\r\n").ok()?;

        // Read and process rebalancing response
        let mut buf = vec![0u8; 8192];
        let n = stream.read(&mut buf).ok()?;
        let _ = xml_config::parse_xml_response(&buf[..n], &self.parser_config);

        Some(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_safe_xml_parsing() {
        let config = xml_config::ParserConfig::secure_defaults();
        let xml = b"<response><key>test</key><value>hello</value><ttl>300</ttl><node>n1</node></response>";
        let result = xml_config::parse_xml_response(xml, &config).unwrap();
        assert_eq!(result.key, "test");
        assert_eq!(result.value, "hello");
    }

    #[test]
    fn test_internal_entity_resolution() {
        let config = xml_config::ParserConfig::secure_defaults()
            .with_entity_resolution(true);
        let xml = b"<!DOCTYPE r [<!ENTITY nodename \"cluster-alpha\">]><response><key>k</key><value>v</value><ttl>60</ttl><node>&nodename;</node></response>";
        let result = xml_config::parse_xml_response(xml, &config).unwrap();
        assert_eq!(result.node_id, "cluster-alpha");
    }

    #[test]
    fn test_external_entity_blocked() {
        let config = xml_config::ParserConfig::secure_defaults()
            .with_entity_resolution(true)
            .with_external_dtd(true)
            .with_network(true);
        let xml = b"<!DOCTYPE r [<!ENTITY xxe SYSTEM \"file:///etc/passwd\">]><response><key>k</key><value>&xxe;</value><ttl>60</ttl><node>n1</node></response>";
        let result = xml_config::parse_xml_response(xml, &config).unwrap();
        // External entity should NOT be resolved - value should contain literal &xxe;
        assert_eq!(result.value, "&xxe;");
    }
}
